design.css:
@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&display=swap');

:root {
  --paper: #F7F2E9;
  --card: #EFE8DB;
  --ink: #0F212D;
  --navy: #14405E;
  --amber: #E8A33D;
  --link: #96590A;
  --muted: #5A6771;
  --redflag: #A33B23;
  --border: #D6CBBA;
  --font-display: 'Newsreader', Georgia, serif;
  --font-body: 'Archivo', sans-serif;
  --font-mono: 'IBM Plex Mono', monospace;
}

/* STATUS BANNER */
.status-banner {
  background: #0F212D;
  color: #E8A33D;
  text-align: center;
  padding: 0.45rem 1rem;
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  position: sticky;
  top: 0;
  z-index: 999;
  border-bottom: 1px solid #E8A33D40;
}

/* BASE */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: var(--font-body);
  background: var(--paper);
  color: var(--ink);
  font-size: 1.0625rem;
  line-height: 1.72;
  -webkit-font-smoothing: antialiased;
}

/* HEADER */
header {
  background: var(--paper);
  border-bottom: 2px solid var(--ink);
  padding: 1.25rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
}

header .site-name {
  font-family: var(--font-display);
  font-weight: 300;
  font-size: 1.6rem;
  letter-spacing: -0.02em;
  color: var(--ink);
  text-decoration: none;
}

header nav a {
  font-family: var(--font-body);
  font-size: 0.85rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--ink);
  text-decoration: none;
  margin-left: 2rem;
  border-bottom: 2px solid transparent;
  padding-bottom: 2px;
  transition: border-color 0.2s;
}

header nav a:hover { border-color: var(--amber); }

/* TYPOGRAPHY */
h1 {
  font-family: var(--font-display);
  font-weight: 300;
  font-size: clamp(2.4rem, 5vw, 4.2rem);
  line-height: 1.12;
  letter-spacing: -0.025em;
  color: var(--ink);
}

h2 {
  font-family: var(--font-display);
  font-weight: 300;
  font-size: clamp(1.7rem, 3.2vw, 2.6rem);
  line-height: 1.18;
  letter-spacing: -0.02em;
}

h3 {
  font-family: var(--font-display);
  font-weight: 400;
  font-size: 1.25rem;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

h4 {
  font-family: var(--font-body);
  font-size: 0.78rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
}

p { margin-top: 0.9em; }
p:first-child { margin-top: 0; }

a { color: var(--link); text-decoration: underline; text-underline-offset: 3px; }
a:hover { color: var(--ink); }

.mono {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--muted);
}

.redflag {
  color: var(--redflag);
  font-family: var(--font-mono);
  font-size: 0.82rem;
  letter-spacing: 0.04em;
}

/* SECTIONS */
.section-paper { background: var(--paper); padding: 5rem 2rem; }
.section-card { background: var(--card); padding: 5rem 2rem; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); }
.section-navy {
  background: var(--navy);
  color: #F7F2E9;
  padding: 5rem 2rem;
}
.section-navy h2, .section-navy h3 { color: #F7F2E9; }
.section-navy h4 { color: #8FA3B1; }
.section-navy p, .section-navy li { color: #D8E4EC; }
.section-navy .mono { color: #8FA3B1; }
.section-navy a { color: var(--amber); }

.section-dark {
  background: var(--ink);
  color: #F7F2E9;
  padding: 5rem 2rem;
}
.section-dark h2, .section-dark h3 { color: #F7F2E9; }
.section-dark h4 { color: #8FA3B1; }
.section-dark p, .section-dark li { color: #C8D6DF; }
.section-dark .mono { color: #8FA3B1; }

.container {
  max-width: 1120px;
  margin: 0 auto;
}

/* HERO */
.hero {
  background: var(--paper);
  padding: 5rem 2rem 4rem;
  border-bottom: 1px solid var(--border);
}

.hero h1 {
  max-width: 820px;
  margin-bottom: 1.5rem;
}

.hero .standfirst {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 300;
  font-style: italic;
  color: var(--muted);
  max-width: 640px;
  margin-bottom: 2.5rem;
  line-height: 1.6;
}

/* BUTTONS / CTA */
.btn {
  display: inline-block;
  font-family: var(--font-body);
  font-size: 0.82rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.7rem 1.5rem;
  border: 2px solid;
  text-decoration: none;
  transition: background 0.18s, color 0.18s;
  cursor: pointer;
}

.btn-amber {
  background: var(--amber);
  color: var(--ink);
  border-color: var(--amber);
}
.btn-amber:hover { background: #d4912e; border-color: #d4912e; color: var(--ink); }

.btn-outline {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-outline:hover { background: var(--ink); color: var(--paper); }

.btn-outline-light {
  background: transparent;
  color: #F7F2E9;
  border-color: #F7F2E9;
}
.btn-outline-light:hover { background: #F7F2E9; color: var(--ink); }

.cta-group { display: flex; gap: 1rem; flex-wrap: wrap; }

/* FIGURE STATS */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 2rem;
  margin-top: 3rem;
}

.stat-card {
  background: var(--card);
  border: 1px solid var(--border);
  padding: 2rem 1.75rem;
  position: relative;
}

.stat-card .figure {
  font-family: var(--font-display);
  font-weight: 300;
  font-size: clamp(3.5rem, 6vw, 5.5rem);
  line-height: 1;
  letter-spacing: -0.04em;
  color: var(--ink);
  display: block;
}

.stat-card .label {
  font-family: var(--font-body);
  font-size: 0.9rem;
  color: var(--muted);
  margin-top: 0.35rem;
  display: block;
}

.stat-card .mono {
  display: block;
  margin-top: 0.9rem;
  padding-top: 0.7rem;
  border-top: 1px solid var(--border);
}

/* PROGRAM CARDS */
.program-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 1.5rem;
  margin-top: 2.5rem;
}

.program-card {
  background: var(--paper);
  border: 1px solid var(--border);
  border-top: 3px solid var(--amber);
  padding: 1.75rem;
}

.program-card .prog-number {
  font-family: var(--font-display);
  font-size: 2.4rem;
  font-weight: 300;
  color: var(--border);
  line-height: 1;
  margin-bottom: 0.25rem;
}

.program-card h3 { margin-bottom: 0.5rem; font-size: 1.1rem; }
.program-card p { font-size: 0.9rem; color: var(--muted); margin-top: 0.4em; }

/* TWO-COL SPLIT */
.split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  margin-top: 2.5rem;
}

@media (max-width: 700px) { .split { grid-template-columns: 1fr; } }

.split-panel {
  padding: 2rem;
  border: 1px solid rgba(255,255,255,0.15);
}

.split-panel h3 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 400;
  color: #F7F2E9;
  border-bottom: 1px solid rgba(255,255,255,0.2);
  padding-bottom: 0.75rem;
  margin-bottom: 1rem;
}

.split-panel .stat-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 0.45rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  font-size: 0.9rem;
}

.split-panel .stat-row .val {
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 300;
  color: var(--amber);
}

/* TABLE */
table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 1.75rem;
  font-size: 0.88rem;
}

th {
  font-family: var(--font-body);
  font-size: 0.72rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--muted);
  text-align: left;
  padding: 0.6rem 0.75rem;
  border-bottom: 2px solid var(--border);
}

td {
  padding: 0.65rem 0.75rem;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}

tr:last-child td { border-bottom: none; }
tbody tr:hover td { background: var(--card); }

/* POLICY TABLE */
.policy-table td:last-child {
  font-weight: 600;
}
.policy-ok { color: #1A6B3A; }
.policy-partial { color: #8C5E00; }
.policy-none { color: var(--redflag); }

/* CALLOUT */
.callout {
  background: var(--amber);
  color: var(--ink);
  padding: 1.5rem 2rem;
  margin: 2rem 0;
  border-left: 5px solid #b87f2a;
}
.callout h4 { color: var(--ink); letter-spacing: 0.06em; margin-bottom: 0.4rem; }
.callout p { color: var(--ink); margin-top: 0; font-size: 0.9rem; }

.callout-dark {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.15);
  border-left: 4px solid var(--amber);
  padding: 1.25rem 1.75rem;
  margin: 1.5rem 0;
}
.callout-dark p { margin-top: 0; font-size: 0.88rem; }

/* FACT LIST */
.fact-list {
  list-style: none;
  margin-top: 1.5rem;
}
.fact-list li {
  padding: 0.9rem 0;
  border-bottom: 1px solid var(--border);
  font-size: 0.95rem;
  line-height: 1.6;
}
.fact-list li:last-child { border-bottom: none; }

/* STEP NUMBERS */
.steps { margin-top: 2.5rem; }
.step {
  display: grid;
  grid-template-columns: 3.5rem 1fr;
  gap: 1.5rem;
  margin-bottom: 2rem;
  align-items: start;
}
.step-num {
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 300;
  color: var(--border);
  line-height: 1;
  padding-top: 0.1rem;
}
.step-body h3 { margin-bottom: 0.35rem; }
.step-body p { font-size: 0.92rem; color: var(--muted); margin-top: 0; }

/* SCHOOL LIST */
.school-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 0.75rem;
  margin-top: 1.75rem;
}
.school-tag {
  background: var(--card);
  border: 1px solid var(--border);
  padding: 0.6rem 1rem;
  font-size: 0.85rem;
  font-weight: 500;
}

/* MEASURE GRID */
.measure-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.5rem;
  margin-top: 2rem;
}
.measure-card {
  padding: 1.25rem;
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.05);
}
.measure-card h4 { color: #8FA3B1; margin-bottom: 0.5rem; }
.measure-card p { font-size: 0.85rem; color: #C8D6DF; margin-top: 0; }

/* COST CARDS */
.cost-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-top: 2rem;
}
@media (max-width: 600px) { .cost-grid { grid-template-columns: 1fr; } }
.cost-card {
  border: 2px dashed var(--border);
  padding: 2.5rem 2rem;
  text-align: center;
}
.cost-card .placeholder-amount {
  font-family: var(--font-display);
  font-size: 3rem;
  font-weight: 300;
  color: var(--redflag);
  display: block;
}
.cost-card p { font-size: 0.85rem; color: var(--muted); margin-top: 0.5rem; }

/* DOCUMENT LIST */
.doc-list { list-style: none; margin-top: 1.5rem; }
.doc-list li {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.8rem 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  font-size: 0.9rem;
  color: #D8E4EC;
}
.doc-list li::before {
  content: '—';
  color: var(--amber);
  font-family: var(--font-mono);
  flex-shrink: 0;
}

/* PACKET CTA */
.packet-cta {
  background: var(--amber);
  color: var(--ink);
  padding: 4rem 2rem;
  text-align: center;
}
.packet-cta h2 { font-size: clamp(1.6rem, 3vw, 2.4rem); color: var(--ink); }
.packet-cta p { font-size: 0.9rem; max-width: 560px; margin: 1rem auto 2rem; color: #2a1800; }
.packet-contents {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  justify-content: center;
  margin: 1.5rem 0 2rem;
  list-style: none;
}
.packet-contents li {
  background: rgba(0,0,0,0.12);
  padding: 0.3rem 0.75rem;
  font-size: 0.78rem;
  font-family: var(--font-mono);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ink);
}

/* FOOTER */
footer {
  background: var(--ink);
  color: #8FA3B1;
  padding: 3rem 2rem;
  font-size: 0.82rem;
}
footer .footer-tagline {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-style: italic;
  font-weight: 300;
  color: #F7F2E9;
  margin-bottom: 1rem;
}
footer .footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 2rem;
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid #1E3A4F;
}
footer a { color: var(--amber); }

/* UTILS */
.eyebrow {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  display: block;
  margin-bottom: 0.75rem;
}
.eyebrow-light {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: #8FA3B1;
  display: block;
  margin-bottom: 0.75rem;
}

.divider { border: none; border-top: 1px solid var(--border); margin: 3rem 0; }
.divider-light { border: none; border-top: 1px solid rgba(255,255,255,0.12); margin: 2rem 0; }

.mt1 { margin-top: 0.5rem; }
.mt2 { margin-top: 1rem; }
.mt3 { margin-top: 1.5rem; }
.mt4 { margin-top: 2rem; }

/* ANIMATION */
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(24px); }
  to { opacity: 1; transform: translateY(0); }
}

.hero h1 { animation: fadeUp 0.7s ease both; }
.hero .standfirst { animation: fadeUp 0.7s 0.15s ease both; }
.hero .cta-group { animation: fadeUp 0.7s 0.3s ease both; }

@media (max-width: 768px) {
  header { padding: 1rem 1.25rem; }
  .section-paper, .section-card, .section-navy, .section-dark { padding: 3.5rem 1.25rem; }
  .hero { padding: 3.5rem 1.25rem; }
  .split { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
  header nav a { margin-left: 1rem; }
}

@media (max-width: 480px) {
  .stats-grid { grid-template-columns: 1fr; }
  .cost-grid { grid-template-columns: 1fr; }
}
